"use strict";

const express = require("express");
const crypto = require("crypto");
const os = require("os");

const app = express();
app.use(express.json({ limit: "1kb" }));

// IoT firmware metadata service for Kubernetes health probes
const FIRMWARE_VERSION = "2.4.1-rc3";
const DEVICE_CLASS = "sensor-gateway";
const MAX_TOPIC_LENGTH = 128;

// MQTT topic validation - topics follow pattern: devices/{id}/telemetry/{stream}
// Valid chars: alphanumeric, hyphens, underscores, forward slashes
// Security: prevent injection via topic strings in MQTT broker
function buildTopicValidator() {
  // Each segment between slashes must be a valid identifier
  // Identifiers: start with letter, followed by alphanumeric/hyphen/underscore
  // We compose the regex from parts for maintainability
  const segmentChar = "[a-zA-Z0-9_-]";
  const segment = `[a-zA-Z]${segmentChar}*`;
  // Full topic: one or more segments separated by /
  // Optional trailing metadata in parentheses for QoS hints: (qos=1)
  const metadataValue = `[a-zA-Z0-9]+`;
  const metadataEntry = `[a-zA-Z]+=${metadataValue}`;
  // Allow multiple comma-separated metadata entries
  const metadataBlock = `\\(${metadataEntry}(?:,${metadataEntry})*\\)`;
  const topicPath = `(?:${segment})(?:/${segment})*`;
  // Final pattern with optional metadata suffix
  const fullPattern = `^${topicPath}(?:\\s+${metadataBlock})?$`;
  return new RegExp(fullPattern);
}

// Device certificate CN validation
// CN format: DEVCLASS-SERIAL-REGION (e.g., sensor-gateway-A1B2C3D4-us-east-1)
function buildCNValidator() {
  const deviceClass = "[a-z]+(?:-[a-z]+)*";
  const serial = "[A-Z0-9]{6,12}";
  const regionPart = "[a-z]+[0-9]*";
  const region = `${regionPart}(?:-${regionPart})*`;
  return new RegExp(`^${deviceClass}-${serial}-${region}$`);
}

// Telemetry payload schema validator
// Validates stringified numeric arrays like: "[1.23, 4.56, 7.89]"
function buildTelemetryValidator() {
  const num = "-?[0-9]+(?:\\.[0-9]+)?(?:[eE][+-]?[0-9]+)?";
  const ws = "\\s*";
  // Array of numbers with flexible whitespace
  return new RegExp(`^\\[${ws}(?:${num}${ws}(?:,${ws}${num}${ws})*)\\]$`);
}

const topicValidator = buildTopicValidator();
const cnValidator = buildCNValidator();
const telemetryValidator = buildTelemetryValidator();

// Rate limiting state
const requestCounts = new Map();
const RATE_WINDOW_MS = 60000;
const MAX_REQUESTS = 100;

function rateLimit(clientId) {
  const now = Date.now();
  const record = requestCounts.get(clientId);
  if (!record || (now - record.windowStart) > RATE_WINDOW_MS) {
    requestCounts.set(clientId, { windowStart: now, count: 1 });
    return true;
  }
  record.count++;
  return record.count <= MAX_REQUESTS;
}

// Authentication middleware - validates device certificate CN from mTLS header
function authenticateDevice(req, res, next) {
  const clientCN = req.headers["x-client-cn"];
  if (!clientCN || clientCN.length > 64) {
    return res.status(401).json({ error: "Missing or invalid client certificate" });
  }
  if (!cnValidator.test(clientCN)) {
    return res.status(401).json({ error: "Invalid certificate CN format" });
  }
  req.deviceId = clientCN;
  next();
}

// Health endpoint for Kubernetes liveness/readiness probes
app.get("/healthz", (req, res) => {
  res.json({
    status: "healthy",
    firmware: FIRMWARE_VERSION,
    deviceClass: DEVICE_CLASS,
    uptime: process.uptime(),
    memory: process.memoryUsage().heapUsed
  });
});

// Telemetry ingestion endpoint
app.post("/api/v1/telemetry", authenticateDevice, (req, res) => {
  const { topic, payload, timestamp } = req.body;

  if (!rateLimit(req.deviceId)) {
    return res.status(429).json({ error: "Rate limit exceeded" });
  }

  // Validate topic
  if (!topic || typeof topic !== "string" || topic.length > MAX_TOPIC_LENGTH) {
    return res.status(400).json({ error: "Invalid topic" });
  }
  if (!topicValidator.test(topic)) {
    return res.status(400).json({ error: "Topic format invalid" });
  }

  // Validate payload
  if (!payload || typeof payload !== "string" || payload.length > 512) {
    return res.status(400).json({ error: "Invalid payload" });
  }
  if (!telemetryValidator.test(payload)) {
    return res.status(400).json({ error: "Payload must be numeric array" });
  }

  // Validate timestamp
  const ts = Number(timestamp);
  if (!Number.isFinite(ts) || ts < 0) {
    return res.status(400).json({ error: "Invalid timestamp" });
  }

  // Process telemetry (simplified - would normally publish to message bus)
  const messageId = crypto.randomUUID();
  console.log(`[${new Date(ts).toISOString()}] ${req.deviceId} -> ${topic}: ${payload.substring(0, 50)}`);

  res.status(202).json({ messageId, accepted: true });
});

// Firmware update check endpoint
app.get("/api/v1/firmware/check", authenticateDevice, (req, res) => {
  res.json({
    currentVersion: FIRMWARE_VERSION,
    latestVersion: FIRMWARE_VERSION,
    updateAvailable: false
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, "0.0.0.0", () => {
  console.log(`IoT firmware service v${FIRMWARE_VERSION} listening on port ${PORT}`);
  console.log(`Device class: ${DEVICE_CLASS}, hostname: ${os.hostname()}`);
});

module.exports = app;
